import pytest

from app.errors import AppError, ValidationError
from app.features.discounts import apply_discount


def test_basic_discount():
    assert apply_discount("19.99", 10) == "$18.00"


def test_zero_percent_keeps_price():
    assert apply_discount("19.99", 0) == "$19.99"


def test_full_discount_is_free():
    assert apply_discount("19.99", 100) == "$0.00"


def test_rounds_discount_down_to_cents():
    # 1005 * 33 // 100 = 331 cents off -> 674
    assert apply_discount("10.05", 33) == "$6.74"


def test_accepts_dollar_sign_and_whole_numbers():
    assert apply_discount("$50", 20) == "$40.00"


@pytest.mark.parametrize("percent", [-1, 101, 1000])
def test_percent_out_of_range_raises(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("percent", [10.5, "10", None, True])
def test_percent_wrong_type_raises(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("price", ["abc", "", "1.234", "-5", "1,000"])
def test_invalid_price_raises(price):
    with pytest.raises(ValidationError):
        apply_discount(price, 10)


def test_errors_are_app_errors():
    with pytest.raises(AppError):
        apply_discount("x", 10)

